-- Provider-authorized Module 8; private resources, no entitlement or release changes.
begin;
insert into public.ce_course1_resources(id,data) values
('illicit_drugs_pdf','{"base64": "", "sha256": "021c2369b63e644c0e616e8e2135d1cc3acf05fcd63b5dd8f3d34a7947a1dd2b", "filename": "CE_HALO_Illicit_Drugs_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('illicit_drugs_questions','[{"module_id": "course_1_module_8", "question_id": "course_1_module_8_q01", "question_number": 1, "stem": "Which of the following BEST describes the modern illicit drug supply that CRNAs now encounter perioperatively?", "choice_a": "A mixed, unstable, and often adulterated environment dominated by illicit fentanyl and polysubstance exposure", "choice_b": "Almost exclusively heroin and cocaine", "choice_c": "Well-labeled prescription products obtained outside pharmacies", "choice_d": "A predictable set of pure single-drug exposures", "correct_choice": "a", "rationale": "The modern era is dominated by illicit fentanyl, polysubstance combinations, and adulterants such as xylazine and nitazenes — reported drug names often underestimate actual exposure (CDC, 2024; Perrone et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q02", "question_number": 2, "stem": "A patient reports \"just a little cocaine\" 45 minutes before scheduled elective surgery and has HR 130, BP 195/108, and chest pain. The MOST appropriate action is:", "choice_a": "Give a beta-blocker and proceed", "choice_b": "Postpone elective surgery and evaluate for stimulant-related cardiac ischemia", "choice_c": "Proceed immediately with induction", "choice_d": "Cancel all future surgery for this patient", "correct_choice": "b", "rationale": "Acute stimulant intoxication with chest pain, tachycardia, and hypertension warrants postponement and workup for coronary vasospasm or ischemia; do not proceed with elective surgery (Mishra et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q03", "question_number": 3, "stem": "Chronic methamphetamine users may respond to induction UNEXPECTEDLY with:", "choice_a": "Immediate hyperkalemia", "choice_b": "Malignant hyperthermia only", "choice_c": "Hypotension due to catecholamine depletion", "choice_d": "Persistent extreme hypertension", "correct_choice": "c", "rationale": "Chronic stimulant use can deplete catecholamine stores, so patients may be hypertensive on arrival but become unexpectedly hypotensive after induction. Titrate and be prepared to support blood pressure (WFSA ATOTW, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q04", "question_number": 4, "stem": "Which best describes xylazine''s clinical relevance to the perioperative CRNA?", "choice_a": "It is a fully naloxone-reversible opioid", "choice_b": "It is only relevant in pediatric patients", "choice_c": "It causes sympathomimetic toxicity indistinguishable from cocaine", "choice_d": "It is a veterinary alpha-2 agonist increasingly adulterating illicit fentanyl; naloxone does NOT reverse its effects", "correct_choice": "d", "rationale": "Xylazine is a veterinary alpha-2 agonist adulterant increasingly in the illicit opioid supply. It contributes to sedation, bradycardia, hypotension, and respiratory depression, and naloxone reverses only the opioid component (Solanki et al., 2024; CDC, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q05", "question_number": 5, "stem": "After naloxone for suspected fentanyl overdose, a patient remains sedated with RR 8. What is the best next step?", "choice_a": "Support ventilation and repeat/titrate naloxone as needed while assessing co-exposure and other causes", "choice_b": "Use full alertness as the only treatment endpoint", "choice_c": "Assume xylazine and stop all naloxone", "choice_d": "Wait without airway support", "correct_choice": "a", "rationale": "Residual or recurrent opioid effect remains possible. Naloxone does not reverse xylazine, but suspected xylazine does not remove the need for opioid reversal.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [1], "source_urls": ["https://www.cdc.gov/overdose-prevention/media/pdfs/2024/07/Xylazine-Clinical-Management-and-Harm-Reduction.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q06", "question_number": 6, "stem": "Nitazenes are BEST described as:", "choice_a": "Non-opioid analgesics with a wide safety margin", "choice_b": "Highly potent synthetic opioids increasingly in the illicit supply, with risk of profound tolerance and refractory overdose", "choice_c": "A class of veterinary alpha-2 agonists", "choice_d": "Benzodiazepines used in club settings", "correct_choice": "b", "rationale": "Nitazenes are highly potent synthetic opioids increasingly identified in the illicit drug supply. They may produce profound tolerance, refractory overdose, and unpredictable sedation (Hamza et al., 2026).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q07", "question_number": 7, "stem": "A patient with daily illicit fentanyl use undergoes ORIF and reports 10/10 pain in PACU despite standard opioid dosing. The MOST appropriate approach is:", "choice_a": "Discharge with home NSAIDs only", "choice_b": "Assume drug-seeking and withhold further analgesia", "choice_c": "Provide multimodal analgesia (regional if appropriate, acetaminophen, NSAIDs where safe, ketamine adjunct) and titrate opioids to effect", "choice_d": "Give flumazenil", "correct_choice": "c", "rationale": "Chronic illicit fentanyl use produces marked tolerance and often opioid-induced hyperalgesia. Multimodal analgesia is essential, and opioid requirements are often higher than expected (Hooten, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q08", "question_number": 8, "stem": "Opioid withdrawal is BEST characterized as:", "choice_a": "Rarely symptomatic", "choice_b": "Indistinguishable from stimulant intoxication", "choice_c": "Reliably life-threatening in every patient", "choice_d": "Typically distressing but not directly life-threatening in most patients — still important to treat perioperatively", "correct_choice": "d", "rationale": "Opioid withdrawal is usually not directly life-threatening but is severe, distressing, and disruptive perioperatively, and can complicate hemodynamics and pain control (Regina et al., 2024; Hooten, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q09", "question_number": 9, "stem": "Which withdrawal syndrome carries the HIGHEST risk of life-threatening deterioration such as seizures and severe autonomic instability?", "choice_a": "Sedative-hypnotic and GHB withdrawal", "choice_b": "Cannabis withdrawal", "choice_c": "Opioid withdrawal in an otherwise healthy adult", "choice_d": "Stimulant crash", "correct_choice": "a", "rationale": "Sedative-hypnotic and GHB withdrawal can progress to severe agitation, autonomic instability, hallucinations, delirium, and seizures — high-acuity monitoring and escalation are often required (Karila et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q10", "question_number": 10, "stem": "A postoperative patient with chronic GHB use becomes rapidly agitated, tremulous, and autonomically unstable. The BEST interpretation is:", "choice_a": "Routine PACU emergence delirium", "choice_b": "Possible GHB withdrawal requiring urgent escalation of monitoring and treatment", "choice_c": "Malingering", "choice_d": "Simple postoperative anxiety", "correct_choice": "b", "rationale": "GHB withdrawal onset may be rapid and severe. In a chronic user showing escalating agitation and autonomic instability, escalate monitoring — do not assume emergence delirium (Karila et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q11", "question_number": 11, "stem": "Which route of illicit drug use MOST directly heightens concern for infective endocarditis, bacteremia, and difficult IV access?", "choice_a": "Oral pill", "choice_b": "Sublingual", "choice_c": "Injection", "choice_d": "Intranasal", "correct_choice": "c", "rationale": "Injection drug use is associated with infective endocarditis, bacteremia, skin and soft tissue infection, hepatitis, HIV, septic emboli, and poor venous access (Quintana et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q12", "question_number": 12, "stem": "Which of the following is the STRONGEST reason to suspect that a reported \"Xanax\" or \"Percocet\" pill purchased outside a pharmacy could contain fentanyl, methamphetamine, or nitazenes?", "choice_a": "Counterfeit pills only affect adolescents", "choice_b": "Only prescription bottles from other countries contain adulterants", "choice_c": "Reported pill names are always accurate", "choice_d": "Counterfeit pill supplies are known to be pharmacologically unreliable and commonly contain unexpected substances", "correct_choice": "d", "rationale": "Counterfeit tablets frequently contain fentanyl, methamphetamine, nitazenes, or other unexpected substances. Treat counterfeit-pill exposure as pharmacologically uncertain (CDC, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [1], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q13", "question_number": 13, "stem": "A patient with acute PCP intoxication presents to the OR. Which finding is MOST expected?", "choice_a": "Agitation, nystagmus, hypertension, and possible violent behavior", "choice_b": "Isolated pinpoint pupils", "choice_c": "Predictable, calm cooperation", "choice_d": "Profound sedation and bradycardia", "correct_choice": "a", "rationale": "PCP typically produces agitation, nystagmus, hypertension, psychosis, hyperthermia, and sometimes violent behavior. Consent capacity may be impaired (Zoppellari et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q14", "question_number": 14, "stem": "A heavy chronic illicit ketamine user may show which additional clinical concern?", "choice_a": "Predictable hypoglycemia", "choice_b": "Chronic urinary tract complications", "choice_c": "Guaranteed cardiomyopathy", "choice_d": "Absence of any tolerance", "correct_choice": "b", "rationale": "Heavy illicit ketamine use is associated with dissociation, tachycardia, hypertension, and chronic urinary complications, and co-use with stimulants or club drugs is common (Zoppellari et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q15", "question_number": 15, "stem": "LSD and psilocybin most typically produce which perioperative concern?", "choice_a": "Profound bradycardia", "choice_b": "Malignant hyperthermia", "choice_c": "Anxiety, panic, perceptual disturbance, and behavioral unpredictability", "choice_d": "Severe cardiorespiratory collapse", "correct_choice": "c", "rationale": "Classic hallucinogens more often create anxiety, panic, perceptual disturbance, and behavioral unpredictability than severe cardiorespiratory toxicity — reassurance and calm environment are usually most useful (Zoppellari et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q16", "question_number": 16, "stem": "During preoperative screening for illicit drug use, the MOST clinically useful questions include all of the following EXCEPT:", "choice_a": "When it was last used", "choice_b": "How it was used (route)", "choice_c": "What substance was used", "choice_d": "Whether the patient''s family morally approves of the use", "correct_choice": "d", "rationale": "Effective preoperative screening focuses on what was used, when, how, how often, current symptoms, and prior complications — not moral judgment (Gould et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q17", "question_number": 17, "stem": "Which of the following BEST justifies postponing an elective procedure in a patient with a substance-use history?", "choice_a": "Current acute intoxication, hyperthermia, uncontrolled chest pain, severe agitation, or impaired consent capacity", "choice_b": "Reported use more than one year ago", "choice_c": "Positive urine toxicology alone with normal exam", "choice_d": "Any past use of a controlled substance", "correct_choice": "a", "rationale": "Elective surgery should be postponed for acute intoxication, hyperthermia, chest pain, agitation, or impaired consent capacity — not for remote use alone (Mishra et al., 2025; Gould et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q18", "question_number": 18, "stem": "A stable patient with a remote history of substance use, no current toxicity, and adequate consent capacity should generally be:", "choice_a": "Refused surgery", "choice_b": "Managed with an anesthetic plan that accounts for tolerance, withdrawal risk, pain needs, and postoperative monitoring", "choice_c": "Fully sedated to \"prevent\" withdrawal", "choice_d": "Treated identically to opioid-naïve patients", "correct_choice": "b", "rationale": "Remote or chronic use without current toxicity is not itself a contraindication. Individualize the plan for tolerance, withdrawal, pain, and monitoring (Gould et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q19", "question_number": 19, "stem": "In the postoperative period, a patient with suspected illicit fentanyl and possible xylazine exposure should ordinarily receive:", "choice_a": "Routine flumazenil administration", "choice_b": "Standard ambulatory discharge criteria", "choice_c": "Extended PACU observation with repeated assessment of sedation, ventilation, and hemodynamics", "choice_d": "Immediate discharge to unmonitored care", "correct_choice": "c", "rationale": "Mixed depressant exposure may cause recurrent hypoventilation and prolonged sedation. Extend observation and reassess repeatedly (Solanki et al., 2024; Hooten, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q20", "question_number": 20, "stem": "Which of the following BEST describes the role of multimodal analgesia in patients with chronic illicit opioid exposure?", "choice_a": "Contraindicated in tolerant patients", "choice_b": "Only relevant for opioid-naïve patients", "choice_c": "Optional add-on rarely needed", "choice_d": "Essential — plan regional techniques, acetaminophen, NSAIDs when safe, and non-opioid adjuncts because opioid-only strategies often fail", "correct_choice": "d", "rationale": "Multimodal analgesia is essential in high-tolerance patients — pure opioid strategies often fail and postoperative opioid needs are usually higher than expected (Hooten, 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q21", "question_number": 21, "stem": "A patient with recent MDMA use presents with hyperthermia, agitation, and hyponatremia. The MOST clinically important perioperative consideration is:", "choice_a": "Address hyperthermia, electrolyte disturbance, and serotonergic effects; consider the risk of dysrhythmia and unpredictable sedative responses", "choice_b": "Immediate elective surgery is safe", "choice_c": "Give routine sympathomimetics to raise BP", "choice_d": "Use spinal anesthesia to bypass all concerns", "correct_choice": "a", "rationale": "MDMA toxicity may produce hyperthermia, hyponatremia, serotonergic effects, dysrhythmia, and unpredictable sedative responses. Stabilize physiology before elective care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [2], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q22", "question_number": 22, "stem": "A postoperative patient with chronic opioid use develops diaphoresis, mydriasis, restlessness, tachycardia, nausea, and diffuse pain. The BEST assessment is:", "choice_a": "Malingering", "choice_b": "Consider concurrent opioid withdrawal AND under-treated pain, and address both", "choice_c": "Definitely simple PACU delirium requiring physical restraint", "choice_d": "Purely anxiety", "correct_choice": "b", "rationale": "A patient can be simultaneously opioid-tolerant, under-treated for pain, and starting to withdraw. Treat both and reassess (Hooten, 2024; Regina et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [3], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q23", "question_number": 23, "stem": "Which of the following BEST reflects the modern CRNA approach to illicit drug exposure?", "choice_a": "Apply a universal 30-day abstinence rule regardless of history", "choice_b": "Treat the tox screen result as the entire clinical picture", "choice_c": "Plan around the patient''s current toxidrome and physiology, using the drug name and tox screen as one input among several", "choice_d": "Refuse care to any patient with a positive screen", "correct_choice": "c", "rationale": "Modern perioperative care is guided by the patient''s current physiology and toxidrome, not a single reported drug name or tox result (Gould et al., 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [4], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q24", "question_number": 24, "stem": "Which of the following statements about naloxone in the perioperative setting is MOST accurate?", "choice_a": "Naloxone reliably reverses cocaine", "choice_b": "Naloxone reverses opioids, xylazine, GHB, and benzodiazepines", "choice_c": "Naloxone should never be used perioperatively", "choice_d": "Naloxone reverses opioids only; persistent sedation may reflect non-opioid co-exposures", "correct_choice": "d", "rationale": "Naloxone reverses the opioid component, not xylazine. Persistent respiratory depression still warrants airway support and repeat/titrated naloxone when residual opioid effect is possible.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [5], "source_ids": [1], "source_urls": ["https://www.cdc.gov/overdose-prevention/media/pdfs/2024/07/Xylazine-Clinical-Management-and-Harm-Reduction.pdf"], "source_provenance": "verified_targeted_update"}, {"module_id": "course_1_module_8", "question_id": "course_1_module_8_q25", "question_number": 25, "stem": "A CRNA is planning care for a patient with a known injection-drug-use history and a new heart murmur. Which additional preoperative concern is MOST important?", "choice_a": "Evaluate for infective endocarditis, sepsis, and possible cardiac complications before elective surgery", "choice_b": "Ignore the murmur — it is unrelated", "choice_c": "Rely on a single normal ECG to exclude cardiac disease", "choice_d": "Cancel all future anesthesia care", "correct_choice": "a", "rationale": "Injection drug use plus a new murmur raises significant concern for infective endocarditis and cardiac complications; evaluate before elective care (Quintana et al., 2024).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [5], "source_ids": [], "source_urls": ["https://www.cdc.gov/coca/media/pdfs/2024/022924_transcript.pdf", "https://www.cdc.gov/overdose-prevention/about/what-you-should-know-about-xylazine.html", "https://pubmed.ncbi.nlm.nih.gov/39443050/", "https://link.springer.com/article/10.1007/s40429-023-00531-1", "https://pubmed.ncbi.nlm.nih.gov/38242642/", "https://resources.wfsahq.org/atotw/the-role-of-intoxica"], "source_provenance": "provider_submitted_content_and_reference_list"}]'::jsonb)
